        +'vec3 c=alb*(vec3(1.45,1.41,1.36)*wrap*mix(.3,1.,ao)+vec3(.16,.19,.25)*(.55+.45*N.y)*ao);'
        +'vec3 H=normalize(Lk+V);float nh=max(dot(N,H),0.);c+=vec3(1.,.98,.96)*(pow(nh,8.)*.05+pow(nh,48.)*.20)*ao;'
        +'vec3 R=reflect(-V,N);float fr=.04+.96*pow(1.-ndv,5.);c+=vec3(.85,.9,1.)*smoothstep(.45,.95,R.y)*fr*.42*ao;'
