      gl.clear(gl.DEPTH_BUFFER_BIT);gl.disable(gl.DEPTH_TEST);
      S.bindQuad('quad');gl.useProgram(S.progs.shadow.p);gl.uniform2f(S.progs.shadow.rot,F.c,F.s);gl.uniformMatrix4fv(S.progs.shadow.vp,false,F.viewProj);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
