      +'.h3d-labo .mk .lb{position:absolute;left:41px;top:50%;transform:translateY(-50%);white-space:nowrap;font:600 9.5px/1 '+MONO+';letter-spacing:.9px;text-transform:uppercase;color:var(--c);opacity:0;pointer-events:none;transition:opacity .25s;text-shadow:0 0 3px #14181F,0 0 6px #14181F,0 0 10px #14181F}'
      +'.h3d-labo .mk .lb::before{content:"";position:absolute;right:calc(100% + 3px);top:50%;width:8px;height:1px;background:color-mix(in srgb,var(--c) 70%,transparent)}'
